            2'd2: begin a = 1; b = 0; c = 1; d = 0; end
            2'd3: begin a = 0; b = 1; c = 0; d = 1; end
        endcase
    end
    // Next state function
    always @(*) begin
        case (state)
            2'd0: nextstate = 2'd1;
            2'd1: if (x) nextstate = 2'd0; else nextstate = 2'd2;
            2'd2: if (x) nextstate = 2'd3; else nextstate = 2'd1;
            2'd3: if (x) nextstate = 2'd2; else nextstate = 2'd0;
        endcase
    end
    // One-hot encode the next state
    assign nextstate_encoded = {~nextstate[1]&~nextstate[0], ~nextstate[1]&nextstate[0], nextstate[1]&~nextstate[0], nextstate[1]&nextstate[0]};
