    // Register the next state (synchronized with the clock)
    always @(posedge clk) nextstate_reg <= nextstate;
    // Transition to the next state on the clock edge
    always @(posedge clk) state <= nextstate_reg;
    // Output function (depends on the current state and the input)
    assign z = a & state[0] | b & ~state[0];
    // Go back to state A on reset
    always @(posedge clk) begin
        if (areset) state <= 2'd0;
    end
